import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.C6QcfH1u.js";const u=JSON.parse('{"title":"Core API (server-core)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/core/index.md","filePath":"reference/core/index.md"}'),r={name:"reference/core/index.md"};function o(d,e,n,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="core-api-server-core" tabindex="-1">Core API (server-core) <a class="header-anchor" href="#core-api-server-core" aria-label="Permalink to &quot;Core API (server-core)&quot;">​</a></h1><p>The Core API is the main REST service of FLAME Hub. It manages analyses, projects, nodes, registries, and master images, and coordinates workflows through AMQP messaging.</p><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Development (from repo root)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server-api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/server-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> privateaim/hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Database</strong> — MySQL, PostgreSQL, or SQLite</li><li><strong>Authup</strong> — OAuth2 identity provider</li><li><strong>Redis</strong> — pub/sub and caching</li><li><strong>RabbitMQ</strong> — AMQP message bus (for worker communication)</li><li><strong>Harbor</strong> (optional) — Docker registry for analysis images</li></ul><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><h3 id="service-specific" tabindex="-1">Service-Specific <a class="header-anchor" href="#service-specific" aria-label="Permalink to &quot;Service-Specific&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>HARBOR_URL</code></td><td>—</td><td>Harbor registry URL</td></tr><tr><td><code>TELEMETRY_URL</code></td><td>—</td><td>Telemetry service URL</td></tr><tr><td><code>VAULT_CONNECTION_STRING</code></td><td><code>start123@http://127.0.0.1:8090/v1/</code></td><td>Vault connection for secrets</td></tr><tr><td><code>MASTER_IMAGES_OWNER</code></td><td><code>PrivateAim</code></td><td>GitHub owner for master images</td></tr><tr><td><code>MASTER_IMAGES_REPOSITORY</code></td><td><code>master-images</code></td><td>GitHub repository name</td></tr><tr><td><code>MASTER_IMAGES_BRANCH</code></td><td><code>master</code></td><td>GitHub branch</td></tr><tr><td><code>SKIP_PROJECT_APPROVAL</code></td><td><code>false</code></td><td>Skip project approval workflow</td></tr><tr><td><code>SKIP_ANALYSIS_APPROVAL</code></td><td><code>false</code></td><td>Skip analysis approval workflow</td></tr></tbody></table><h3 id="inherited" tabindex="-1">Inherited <a class="header-anchor" href="#inherited" aria-label="Permalink to &quot;Inherited&quot;">​</a></h3><p>See <a href="/reference/#shared-configuration">Shared Configuration</a> and <a href="/reference/#database-configuration">Database Configuration</a>.</p><h2 id="key-endpoints" tabindex="-1">Key Endpoints <a class="header-anchor" href="#key-endpoints" aria-label="Permalink to &quot;Key Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET/POST/DELETE</code></td><td><code>/analyses</code></td><td>Analysis CRUD (update is <code>POST /analyses/:id</code>)</td></tr><tr><td><code>GET/POST/DELETE</code></td><td><code>/projects</code></td><td>Project CRUD</td></tr><tr><td><code>GET/POST/DELETE</code></td><td><code>/nodes</code></td><td>Node CRUD</td></tr><tr><td><code>GET/POST/DELETE</code></td><td><code>/registries</code></td><td>Registry CRUD</td></tr><tr><td><code>GET/DELETE</code></td><td><code>/master-images</code></td><td>Master image read + delete (<code>POST /master-images/command</code> runs sync/build)</td></tr><tr><td><code>GET/POST</code></td><td><code>/nodes/:id/client/credentials</code></td><td>Read / update the node&#39;s OAuth2 client credentials (secret, name, display name) — usable by the node&#39;s own client or a <code>NODE_UPDATE</code> manager</td></tr><tr><td><code>GET</code></td><td><code>/nodes/:id/registry/credentials</code></td><td>Read the node&#39;s own registry project (Harbor robot) credentials — accessible to the node&#39;s own client without any management permission</td></tr><tr><td><code>GET/POST</code></td><td><code>/analyses/:id/client/credentials</code></td><td>Read / rotate the analysis&#39;s OAuth2 client credentials</td></tr><tr><td><code>POST</code></td><td><code>/analyses/:id/storage/token</code></td><td>Mint a storage capability token for buckets and files of the analysis (see below)</td></tr><tr><td><code>GET</code></td><td><code>/docs</code></td><td>Swagger/OpenAPI documentation</td></tr></tbody></table><h2 id="response-shapes" tabindex="-1">Response Shapes <a class="header-anchor" href="#response-shapes" aria-label="Permalink to &quot;Response Shapes&quot;">​</a></h2><p>Every entity endpoint answers with a <code>{ data, meta }</code> envelope — the record (or the record array) under <code>data</code>, response-scoped extras under <code>meta</code>. Query-capable <code>GET</code>s additionally advertise the endpoint&#39;s queryable vocabulary at <code>meta.schema</code>; mutations carry <code>meta: {}</code>.</p><p>Four surfaces of this service deliberately stay <strong>flat</strong>, because they are protocol, credential or bulk-delete shapes rather than entity records:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Shape</th></tr></thead><tbody><tr><td><code>GET /</code></td><td><code>{ version, timestamp }</code> — service metadata</td></tr><tr><td><code>POST /services/:id/hook</code>, <code>POST /services/:id/command</code></td><td><code>null</code> (202) — Harbor webhook / command protocol</td></tr><tr><td><code>GET</code>/<code>POST</code> <code>/nodes/:id/client/credentials</code>, <code>GET</code>/<code>POST</code> <code>/analyses/:id/client/credentials</code>, <code>GET /nodes/:id/registry/credentials</code>, <code>POST /analyses/:id/storage/token</code></td><td>credential payloads</td></tr><tr><td><code>DELETE /analysis-logs</code>, <code>DELETE /analysis-node-logs</code></td><td><code>null</code> (202)</td></tr></tbody></table><p><code>GET /analyses/:id/client/permissions</code> is a collection but carries <strong>no</strong> <code>meta.schema</code> — it proxies Authup <code>ClientPermission</code> records, for which no Hub-side query schema exists.</p><p>See <a href="/guide/development/api.html#response-shapes">API Reference</a> for the full contract and the <code>meta.schema</code> reading rules.</p><h2 id="storage-capability-tokens" tabindex="-1">Storage Capability Tokens <a class="header-anchor" href="#storage-capability-tokens" aria-label="Permalink to &quot;Storage Capability Tokens&quot;">​</a></h2><p><code>POST /analyses/:id/storage/token</code> mints a short-lived, resource-scoped token that <a href="/reference/storage/#capability-tokens">server-storage</a> accepts instead of the caller&#39;s login. A browser then reaches only the buckets and files of one analysis, for only the requested actions.</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /analyses/:id/storage/token</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;access token&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cap&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bucket:&lt;bucketId&gt;:read,write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bucket-file:&lt;fileId&gt;:read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;lifetime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>cap</code></td><td>1 to 32 entries <code>type:id:actions</code> (actions comma-separated). Types <code>bucket</code> (<code>read</code>, <code>write</code>, <code>delete</code>) and <code>bucket-file</code> (<code>read</code>, <code>delete</code>). <code>id</code> is the <strong>storage</strong> bucket or file id.</td></tr><tr><td><code>lifetime</code></td><td>Optional, seconds, 1 to 3600 (default 3600).</td></tr></tbody></table><p>The answer is flat (no <code>{ data, meta }</code> envelope): <code>{ &quot;token&quot;: &quot;...&quot;, &quot;expiresAt&quot;: &quot;&lt;ISO date&gt;&quot; }</code>.</p><p>Core decides access first, then exchanges the caller&#39;s access token for a capability token at Authup (RFC 8693), acting as the Hub client (<code>CLIENT_ID</code>). Every entry must belong to the analysis in the path, and the caller must be allowed every requested action:</p><table tabindex="0"><thead><tr><th>Action</th><th>Rule</th></tr></thead><tbody><tr><td><code>read</code></td><td>The file read rule of the bucket&#39;s type: <code>CODE</code> needs any participation, <code>TEMP</code> an approved node, <code>RESULT</code> an approved node plus <code>analysis_result_read</code></td></tr><tr><td><code>write</code></td><td>The file create rule: <code>CODE</code> owner and unlocked, <code>RESULT</code>/<code>TEMP</code> system or participant uploader</td></tr><tr><td><code>delete</code></td><td>The file delete rule: owner plus a writable bucket</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Status</th><th>Cause</th></tr></thead><tbody><tr><td>200</td><td>Token minted</td></tr><tr><td>400</td><td>Malformed entry, unsupported type or action, or an entry outside the analysis (the whole request fails)</td></tr><tr><td>401</td><td>No access token, or core refused it</td></tr><tr><td>403</td><td>An action is not allowed</td></tr><tr><td>404</td><td>Unknown analysis</td></tr><tr><td>501</td><td><code>AUTHUP_URL</code> is not configured</td></tr><tr><td>502</td><td>Authup refused the exchange (any refusal, including <code>invalid_grant</code>) or is unreachable (check the <a href="/guide/deployment/configuration.html#storage-capability-tokens">deployment setup</a>)</td></tr></tbody></table><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>The Core API follows the <a href="/getting-started/architecture.html">hexagonal architecture</a> with:</p><ul><li><strong>Domain services</strong> for each entity (validation, permission checks, business logic)</li><li><strong>AMQP aggregators</strong> consuming events from other services (builder, distributor, storage, authup)</li><li><strong>AMQP task consumers</strong> for registry and analysis metadata processing</li><li><strong>TypeORM subscribers</strong> publishing domain events on entity changes</li></ul><h2 id="stuck-builds-and-distributions" tabindex="-1">Stuck Builds and Distributions <a class="header-anchor" href="#stuck-builds-and-distributions" aria-label="Permalink to &quot;Stuck Builds and Distributions&quot;">​</a></h2><p>A build or distribution that stays <code>starting</code>/<code>started</code> while its analysis has not been written for 15 minutes is treated as orphaned (e.g. the worker died mid-run). Every 5 minutes — and once at start — server-core re-runs the build/distribution check for such analyses <strong>when AMQP is configured</strong>. Without AMQP the reconciler is not scheduled: no external worker can consume its checks from the local memory bus. If the image is not there, the check result marks the process <code>failed</code>, so it can be started again. Ordinary status and heartbeat saves no longer query Authup for an unchanged, non-null analysis client binding. Creating an analysis or saving it with a missing/changed binding still provisions or checks its client. Deleting a client remotely is not repaired by an unrelated status save. The public analysis update API does not accept <code>clientId</code>, so recovery requires administrative intervention; do not rely on background progress traffic to repair deleted clients. This fast path covers saves of loaded rows, not arbitrary partial TypeORM saves.</p><p>A running worker keeps its analysis fresh with progress events and a 5-minute heartbeat, so a long build or push is not mistaken for a stuck one; a worker progress event that changes nothing writes the analysis at most once a minute. The heartbeat stops once a single step has sent no progress for 2 hours, so a hung build or push makes its analysis stale. That alone does not recover it: with a single worker, the check waits behind the hung run in the same queue, so recovery needs a worker restart, a second worker replica, or RabbitMQ&#39;s <code>consumer_timeout</code> ending the hung delivery.</p><p>A distribution whose check can never decide — its analysis has no nodes, no registry, or a node without a registry project — is reported as still running, so it is failed once stale like a missing image. A late finish from the worker does not revive a build or distribution that was already marked <code>failed</code> (or reset): only a process still <code>starting</code>/<code>started</code> can finish.</p><p>Master-image builds are not covered: they have no check command, and starting a new build takes over one that has been stale for 15 minutes. A fresh <code>starting</code> <strong>or</strong> <code>started</code> build refuses another BUILD. A takeover renews the claim timestamp even if it was already <code>starting</code>. A dispatch error leaves that fresh claim active: the broker may have accepted the command despite a missing confirmation. Worker outcomes are still recorded after the request fails. If nothing was delivered, retry only after the 15-minute stale threshold; an immediate retry is refused to avoid launching a second build. Worker start/progress/failure/finish events apply only while the build is active; late events cannot overwrite a terminal or reset state. Master-image workers do not send the analysis heartbeat: a healthy Docker step silent for over 15 minutes can still be reclaimed. Events still have no run identifier, so a previous run&#39;s delayed event can affect a later active run.</p><h2 id="registry-project-renames" tabindex="-1">Registry project renames <a class="header-anchor" href="#registry-project-renames" aria-label="Permalink to &quot;Registry project renames&quot;">​</a></h2><p>Updates to a node or registry project&#39;s <code>externalName</code> start an asynchronous same-registry migration: copy and verify artifacts, provision destination credentials, then switch the active registry-project binding. Until success, record reads and credential requests continue to return the source namespace. The source project and its robot remain available after cutover; consumers derive image locations from the binding rather than a stored image URL column. Master-image project renames are rejected.</p><p>Pause writers and drain distributions before renaming. Source inventory checks are not a fence against concurrent external pushes. See <a href="/guide/deployment/configuration.html#registry-project-renames">Registry project renames</a> for rollout, retries, retained sources and manual retirement requirements.</p><h2 id="approval-workflows" tabindex="-1">Approval Workflows <a class="header-anchor" href="#approval-workflows" aria-label="Permalink to &quot;Approval Workflows&quot;">​</a></h2><p>By default, projects and analyses require administrator approval before execution. This can be disabled for development:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SKIP_PROJECT_APPROVAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SKIP_ANALYSIS_APPROVAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre></div><p>See <a href="/guide/user/approval.html">Approval Workflows</a> for details on the approval process.</p>`,42)])])}const k=t(r,[["render",o]]);export{u as __pageData,k as default};
